changeSet.sql:
create or alter procedure [fusion].[ProcessFusionCacheInQueue]
@FusionID int, @UseNewMarkitLineage bit = 0
as begin SET NOCOUNT, ANSI_PADDING ON; SET ANSI_WARNINGS ON;
UPDATE FusionAttribute SET TextPath = utility.GetBreadcrumbStringWrapper('FusionAttribute', ID, '.') FROM FusionAttribute WHERE FusionID = @FusionID and deleted = 0
declare @fusionTypeId int;
select @fusionTypeId = fusiontypeid from fusion where id = @FusionID;
if @fusionTypeId = 13 begin exec fusion.GenerateMarkitMapLineageData @FusionID, @UseNewMarkitLineage end else if @fusionTypeId = 16 begin exec [fusion].[GenerateEagleLineageData] @FusionID end else if @fusionTypeId = 111 begin exec [fusion].[GenerateFoundationLineage] @FusionID end
end
